  xma10 Vhigh Vbias1 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma10} l={L_xma10}
  xma11 Vncas Vbias2 N008 VDD sky130_fd_pr__pfet_01v8 w={W_xma11} l={L_xma11}
  xma12 N008 Vbias1 VDD VDD sky130_fd_pr__pfet_01v8 w={W_xma12} l={L_xma12}
  xm16 Vncas Vncas N012 0 sky130_fd_pr__nfet_01v8 w={W_xm16} l={L_xm16}
  xm17 N012 Vbias3 P001 0 sky130_fd_pr__nfet_01v8 w={W_xm17} l={L_xm17}
  xm18 P001 N012 0 0 sky130_fd_pr__nfet_01v8 w={W_xm18} l={L_xm18}
.ends SUB_1
* ---------------------------

.control
  * 1. DC Operating Point for Power
  op
  let power_dissipation = -i(Vdd) * 1.8
  print power_dissipation

  * 2. AC Analysis for Frequency Response
  ac dec 100 1 1G
  let gain_db = vdb(vout)
  let phase_deg = 180/PI * cph(v(vout))

  * Measure Open-Loop Gain (at 1 Hz)
  meas ac aol_db find gain_db at=1

  * Measure Dominant Pole (-3dB frequency)
  let target_gain = aol_db - 3
  meas ac f1_3db when gain_db = target_gain fall=1

  * Measure Unity Gain Frequency (0dB crossing)
  meas ac fun when gain_db = 0 fall=1

  * Measure Phase Margin
  meas ac phase_at_fun find phase_deg when gain_db = 0 fall=1
  * Since it's a non-inverting setup, phase starts at 0 and drops.
  * PM = phase_at_fun - (-180) = phase_at_fun + 180
  let pm = phase_at_fun + 180
  print pm

  * Measure Gain Margin
  meas ac gain_at_180 find gain_db when phase_deg = -180 fall=1
  let gm = 0 - gain_at_180
  print gm

  quit
.endc

